ПутьКОбработке = КаталогСтруктурыТекущейБазы + "\DataProcessors\ExtCntrl";

Результат = "=== КОД-РЕВЬЮ ОБРАБОТКИ ExtCntrl ===" + Символы.ПС + Символы.ПС;

МассивФайлов = НайтиФайлы(ПутьКОбработке, "*.bsl", Истина);

Если МассивФайлов.Количество() = 0 Тогда
    Результат = Результат + "ОШИБКА: Файлы модулей не найдены по пути: " + ПутьКОбработке;
Иначе
    Для Каждого ФайлМодуля Из МассивФайлов Цикл
        ОтносительныйПуть = СтрЗаменить(ФайлМодуля.ПолноеИмя, ПутьКОбработке + "\", "");

        ТипМодуля = "Неизвестный";
        Если Найти(ОтносительныйПуть, "ObjectModule") > 0 Тогда
            ТипМодуля = "Модуль объекта";
        ИначеЕсли Найти(ОтносительныйПуть, "ManagerModule") > 0 Тогда
            ТипМодуля = "Модуль менеджера";
        ИначеЕсли Найти(ОтносительныйПуть, "Form\Module") > 0 Тогда
            ТипМодуля = "Модуль формы";
        ИначеЕсли Найти(ОтносительныйПуть, "CommandModule") > 0 Тогда
            ТипМодуля = "Модуль команды";
        КонецЕсли;

        Чтение = Новый ЧтениеТекста(ФайлМодуля.ПолноеИмя, КодировкаТекста.UTF8);
        Содержимое = Чтение.Прочитать();
        Чтение.Закрыть();

        КоличествоСтрок = СтрЧислоСтрок(Содержимое);
        КоличествоПроцедур = СтрЧислоВхождений(НРег(Содержимое), "процедура ");
        КоличествоФункций = СтрЧислоВхождений(НРег(Содержимое), "функция ");

        Результат = Результат + "=== " + ТипМодуля + " ===" + Символы.ПС;
        Результат = Результат + "Путь: " + ОтносительныйПуть + Символы.ПС;
        Результат = Результат + "Строк: " + КоличествоСтрок + 
                    " | Процедур: " + КоличествоПроцедур + 
                    " | Функций: " + КоличествоФункций + Символы.ПС;
        Результат = Результат + "Размер: " + ФайлМодуля.Размер() + " байт" + Символы.ПС;
        Результат = Результат + "--- СОДЕРЖИМОЕ ---" + Символы.ПС;
        Результат = Результат + Содержимое + Символы.ПС;
        Результат = Результат + "--- КОНЕЦ ---" + Символы.ПС + Символы.ПС;
    КонецЦикла;
КонецЕсли;
